import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from ml import *
tee('m18'); reset()
n = Node('m18'); n.start(); c = n.client(); db = c.test
fill(db.t, 100000, lambda i: {'_id': i, 'a': i % 100, 'b': i % 1000, 'c': (i * 7919) % 100003})
db.t.create_index('a'); db.t.create_index('b'); db.t.create_index([('a', 1), ('b', 1)])
Q = '{a: 5, b: {$gte: 500}}'
print('== 一:queryPlanner(默认):只做计划选择,不执行查询——没有 executionStats,能看到赢家和被淘汰的计划')
msh(n, EXJS.replace('var st = e.executionStats || {};', 'var st = {};') + f'var e = db.t.find({Q}).explain("queryPlanner"); ({{keys: Object.keys(e), plan: chain((e.queryPlanner.winningPlan.queryPlan || e.queryPlanner.winningPlan)), rejected: e.queryPlanner.rejectedPlans.map(p => chain(p.queryPlan || p)), hasExecutionStats: e.executionStats !== undefined}})', label=f'db.t.find({Q}).explain("queryPlanner")', n=40)
print('== 二:executionStats:真的执行查询,给出 nReturned、检查了多少键和文档、耗时,以及执行树上每个阶段的 works / advanced')
msh(n, EXJS + f'var e = db.t.find({Q}).explain("executionStats"); ex(e)', label=f'db.t.find({Q}).explain("executionStats")')
msh(n, f'var e = db.t.find({Q}).explain("executionStats"); var s = e.executionStats.executionStages; var out = []; while (s) {{ out.push({{stage: s.stage, nReturned: s.nReturned, works: s.works, advanced: s.advanced}}); s = s.inputStage }} out', label='  executionStats.executionStages 沿 inputStage 往下展开', n=30)
print('== 三:allPlansExecution:连落选的候选计划各自试跑的统计也给出来')
msh(n, f'var e = db.t.find({Q}).explain("allPlansExecution"); ({{winner: e.queryPlanner.winningPlan.queryPlan ? "(SBE)" : "classic", candidates: e.executionStats.allPlansExecution === undefined ? "(没有 allPlansExecution 字段)" : e.executionStats.allPlansExecution.map(p => ({{nReturned: p.nReturned, keysExamined: p.totalKeysExamined, docsExamined: p.totalDocsExamined, works: p.executionStages ? p.executionStages.works : undefined}}))}})', label=f'db.t.find({Q}).explain("allPlansExecution")', n=40)
print('== 四:explain 不会真的修改数据:对 updateMany / deleteMany 做 explain,文档数不变')
msh(n, 'db.t.countDocuments({})')
msh(n, 'var e = db.runCommand({explain: {update: "t", updates: [{q: {a: 5, b: 505}, u: {$set: {z: 1}}, multi: true}]}, verbosity: "executionStats"}); ({stage: e.executionStats.executionStages.stage, nWouldModify: e.executionStats.executionStages.nWouldModify, docsExamined: e.executionStats.totalDocsExamined})')
msh(n, 'var e = db.runCommand({explain: {delete: "t", deletes: [{q: {a: 5}, limit: 0}]}, verbosity: "executionStats"}); ({stage: e.executionStats.executionStages.stage, nWouldDelete: e.executionStats.executionStages.nWouldDelete, docsExamined: e.executionStats.totalDocsExamined})')
msh(n, 'db.t.countDocuments({}) + " 个文档;有 z 字段的 " + db.t.countDocuments({z: {$exists: true}}) + " 个"')
print('== 五:aggregate 的 explain:$match 和后面的 $group 一起被下推进查询引擎,整个 pipeline 是一个计划;字段都在索引里,还成了覆盖查询')
msh(n, EXJS + f'var e = db.t.explain("executionStats").aggregate([{{$match: {Q}}}, {{$group: {{_id: "$a", n: {{$sum: 1}}}}}}]); ({{stages: e.stages ? e.stages.map(s => Object.keys(s)[0]) : "(没有 stages 字段)", plan: chain(e.queryPlanner.winningPlan.queryPlan || e.queryPlanner.winningPlan), docsExamined: e.executionStats.totalDocsExamined}})', label=f'db.t.explain("executionStats").aggregate([{{$match: {Q}}}, {{$group: {{_id: "$a", n: {{$sum: 1}}}}}}])')
print('== 六:explain(true) 等价于 "allPlansExecution";explain 只是模式不同,同一条查询看到的信息量逐级增加')
msh(n, f'var b = Object.keys(db.t.find({Q}).explain("executionStats").executionStats), d = Object.keys(db.t.find({Q}).explain(true).executionStats); ({{queryPlanner_has_executionStats: Object.keys(db.t.find({Q}).explain("queryPlanner")).includes("executionStats"), executionStats_keys: b, allPlans_extra: d.filter(k => !b.includes(k))}})', note='比较三种模式的输出里有哪些键', n=40)
n.stop()
